BEGIN;

-- Enlaza a Yiyo Sarante en las fichas de Julián Oro Duro y Chiquito Team Band.

UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Julián Oro Duro —Gilberto Julián Sarante Perdomo— is a Dominican merengue singer, songwriter and arranger from Santo Domingo, known for the street merengue of the early 2000s and for leading the orchestra Oro Duro. He is the older brother of the salsa singer "},{"type":"artistReference","attrs":{"occurrenceId":"51ed8103-e075-4f23-b5ab-cff1dfad13d8","artistId":"0d54316a-0114-4754-ae89-72a87ed7069c","displayText":"Yiyo Sarante"}},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"text":"The orchestra and the family","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"In the 1980s and 1990s he fronted the orchestra Oro Duro. His younger brother "},{"type":"artistReference","attrs":{"occurrenceId":"bf15bbac-f7d1-46a2-8131-6043f3291560","artistId":"0d54316a-0114-4754-ae89-72a87ed7069c","displayText":"Yiyo Sarante"}},{"type":"text","text":" sang in its chorus before going independent with a project of his own. Dominican media later reported a period of estrangement between the brothers and their public reconciliation."}]},{"type":"paragraph","content":[{"text":"Solo career and «La Cabaña»","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"He began a solo career in 2000 and became one of the exponents of merengue de calle, a current that was widely welcomed by young Dominicans. His album «La Cabaña», released on 20 December 2004 by «J&N Records», has thirteen songs, among them «La Cabaña», «La Cita», «Por Eso Está Conmigo», «Historia Entre Tus Dedos», «Y Te Vi», «La Querida» and «El Licor». Later albums include «El Más Duro» and «Pa’ lo Mambero». The press noted that his style opened the way for ","type":"text"},{"type":"artistReference","attrs":{"artistId":"d2c0eb06-4b6e-45d1-b795-3778cdf82488","displayText":"Juliana O''Neal","occurrenceId":"18c83a8c-2517-445c-9930-c924187e9adb"}},{"text":", who emerged with a similar proposal before settling on romantic merengue.","type":"text"}]},{"type":"paragraph","content":[{"text":"Songwriter","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"In 2005 he was nominated for a Casandra Award as Composer of the Year for «Palabritas» and «Ni el odio ni la mentira», both recorded by ","type":"text"},{"type":"artistReference","attrs":{"artistId":"9da4edbe-7d7e-4bf1-8c23-ee01bb5ee65b","displayText":"El Jeffrey","occurrenceId":"3b3d2fcb-e4b8-466a-adea-b1945ec5e81e"}},{"text":"; the second is on the 2004 album «Mi Tierra».","type":"text"}]},{"type":"paragraph","content":[{"text":"Since 2010","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"From 2010 he widened his repertoire to romantic merengue, salsa, bachata and merengue mambo. The album «Jaque Mate», with twelve songs, includes «Sé que llorarás» and «No hace falta papá».","type":"text"}]},{"type":"paragraph","content":[{"text":"Legacy","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Dominican newspapers describe him as a frequent presence at parties and stages during the years of merengue de calle, and El Día credits his 2004 album «La Cabaña» with making him known to a mass audience.","type":"text"}]}]}'::jsonb, revision = revision + 1, updated_at = now() WHERE id = (SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id WHERE a.slug = 'julian-oro-duro' AND d.locale = 'en' AND d.document_type = 'artist_biography');
INSERT INTO editorial_entity_references (editorial_document_id, occurrence_id, entity_type, target_artist_id) VALUES ((SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id WHERE a.slug = 'julian-oro-duro' AND d.locale = 'en' AND d.document_type = 'artist_biography'), '51ed8103-e075-4f23-b5ab-cff1dfad13d8', 'artist', '0d54316a-0114-4754-ae89-72a87ed7069c');
INSERT INTO editorial_entity_references (editorial_document_id, occurrence_id, entity_type, target_artist_id) VALUES ((SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id WHERE a.slug = 'julian-oro-duro' AND d.locale = 'en' AND d.document_type = 'artist_biography'), 'bf15bbac-f7d1-46a2-8131-6043f3291560', 'artist', '0d54316a-0114-4754-ae89-72a87ed7069c');

UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Julián Oro Duro —Gilberto Julián Sarante Perdomo— es un cantante, compositor y arreglista dominicano de merengue, nacido en Santo Domingo, conocido por el merengue de calle de los primeros años de los 2000 y por dirigir la orquesta Oro Duro. Es hermano mayor del salsero "},{"type":"artistReference","attrs":{"occurrenceId":"c512d5e4-c6c0-496a-9bdb-319b9c6a0973","artistId":"0d54316a-0114-4754-ae89-72a87ed7069c","displayText":"Yiyo Sarante"}},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"text":"La orquesta y la familia","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"En los años ochenta y noventa estuvo al frente de la orquesta Oro Duro. Su hermano menor "},{"type":"artistReference","attrs":{"occurrenceId":"6543f9ad-979a-4283-9cc0-4a172f666e19","artistId":"0d54316a-0114-4754-ae89-72a87ed7069c","displayText":"Yiyo Sarante"}},{"type":"text","text":" cantó en el coro de esa orquesta antes de independizarse con un proyecto propio. Medios dominicanos informaron después de un distanciamiento entre los hermanos y de su reconciliación pública."}]},{"type":"paragraph","content":[{"text":"Carrera en solitario y «La Cabaña»","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Inició su carrera en solitario en 2000 y fue uno de los exponentes del merengue de calle, una corriente que tuvo amplia acogida entre los jóvenes dominicanos. Su álbum «La Cabaña», publicado el 20 de diciembre de 2004 por «J&N Records», tiene trece canciones, entre ellas «La Cabaña», «La Cita», «Por Eso Está Conmigo», «Historia Entre Tus Dedos», «Y Te Vi», «La Querida» y «El Licor». Entre sus discos posteriores están «El Más Duro» y «Pa’ lo Mambero». La prensa señaló que su estilo abrió camino a ","type":"text"},{"type":"artistReference","attrs":{"artistId":"d2c0eb06-4b6e-45d1-b795-3778cdf82488","displayText":"Juliana O''Neal","occurrenceId":"2ddcff4f-e617-4348-8077-51387943fb29"}},{"text":", que surgió con una propuesta parecida antes de decantarse por el merengue romántico.","type":"text"}]},{"type":"paragraph","content":[{"text":"Compositor","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"En 2005 fue nominado a los Premios Casandra como Compositor del Año por «Palabritas» y «Ni el odio ni la mentira», ambas grabadas por ","type":"text"},{"type":"artistReference","attrs":{"artistId":"9da4edbe-7d7e-4bf1-8c23-ee01bb5ee65b","displayText":"El Jeffrey","occurrenceId":"235698ce-36b3-45a0-bebf-42aeb3249d03"}},{"text":"; la segunda está en el álbum «Mi Tierra» de 2004.","type":"text"}]},{"type":"paragraph","content":[{"text":"Desde 2010","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"A partir de 2010 amplió su repertorio al merengue romántico, la salsa, la bachata y el merengue mambo. El álbum «Jaque Mate», de doce canciones, incluye «Sé que llorarás» y «No hace falta papá».","type":"text"}]},{"type":"paragraph","content":[{"text":"Legado","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Los periódicos dominicanos lo describen como una presencia frecuente en fiestas y escenarios durante los años del merengue de calle, y El Día atribuye a su álbum «La Cabaña» de 2004 haberlo dado a conocer a un público masivo.","type":"text"}]}]}'::jsonb, revision = revision + 1, updated_at = now() WHERE id = (SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id WHERE a.slug = 'julian-oro-duro' AND d.locale = 'es' AND d.document_type = 'artist_biography');
INSERT INTO editorial_entity_references (editorial_document_id, occurrence_id, entity_type, target_artist_id) VALUES ((SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id WHERE a.slug = 'julian-oro-duro' AND d.locale = 'es' AND d.document_type = 'artist_biography'), 'c512d5e4-c6c0-496a-9bdb-319b9c6a0973', 'artist', '0d54316a-0114-4754-ae89-72a87ed7069c');
INSERT INTO editorial_entity_references (editorial_document_id, occurrence_id, entity_type, target_artist_id) VALUES ((SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id WHERE a.slug = 'julian-oro-duro' AND d.locale = 'es' AND d.document_type = 'artist_biography'), '6543f9ad-979a-4283-9cc0-4a172f666e19', 'artist', '0d54316a-0114-4754-ae89-72a87ed7069c');

UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Chiquito Team Band is a Dominican salsa orchestra from Santo Domingo, led by the timbalero Rafael Berroa, known as Chiquito, and by Emmanuel Frías. Its own channel dates its founding to 30 June 2012.","type":"text"}]},{"type":"paragraph","content":[{"text":"Formation","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Salsa-history pages say the two decided to start a new project called Chiquito Team Band, which gradually caught on; a music directory instead dates the group to 2011 and names Kelvin Saviñón as a co-founder. Berroa and Frías told Diario Libre in 2018 that it had taken them twenty years to reach success, and that they came from humble backgrounds.","type":"text"}]},{"type":"paragraph","content":[{"text":"Records","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"The group released the single «Lejos de ti» in March 2014 and its first album, «La industria salsera», in September 2014. «Tengo que colgar» and «Me marcho» followed in 2017, and its second album, «Los creadores del sonido», appeared in March 2018. The single «Ábreme los caminos», an unreleased song by the composer Osmany Espinosa produced by Frías, announced that album, which carried a symphonic sound with arrangements by ","type":"text"},{"type":"artistReference","attrs":{"artistId":"ead3e58c-4592-489b-b5d4-0319f1f6f374","displayText":"Amaury Sánchez","occurrenceId":"de8cbc66-3472-47ad-a2f8-5cec590c7de3"}},{"text":"; the band had previewed the concept at the Festival Presidente. It later released «Me voy a gozar la vida» and «La rumba ta’ buena» (2021), «Ya supérame» (February 2022) and the album «Sin rodeos» (September 2022).","type":"text"}]},{"type":"paragraph","content":[{"text":"Touring and awards","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"In 2018 the band planned a tour of the United States and appearances at the Veracruz carnivals in Mexico, where it said its music is played, and looked back on 2017 visits to Panama, the United States, Colombia and Puerto Rico. It said then that it had been nominated to the Premios Soberano every year since its debut and had won four statuettes, one as Revelation and the rest as salsa group of the year. In March 2023 Diario Libre reported that it was named best salsa group again at that year’s Soberano ceremony.","type":"text"}]},{"type":"paragraph","content":[{"text":"Legacy","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"In 2018 Berroa named as other Dominican acts that keep salsa alive "},{"type":"artistReference","attrs":{"occurrenceId":"b7939cd8-8f7d-4e01-819f-22ac9a161303","artistId":"0d54316a-0114-4754-ae89-72a87ed7069c","displayText":"Yiyo Sarante"}},{"type":"text","text":", "},{"type":"artistReference","attrs":{"artistId":"e324ca2d-27a5-491b-97e7-f8c81396cfcc","displayText":"Asdrubar","occurrenceId":"f4915f54-70ea-4947-9c4e-50780b0f35df"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"33a84471-9f35-4a4f-9b56-b6a61e13212a","displayText":"Revolución Salsera","occurrenceId":"ec0e32d8-7512-4b97-933a-0f10cc45e619"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"d1e84a54-f60c-4b1a-8c12-5195d39c6f5a","displayText":"Sexappeal","occurrenceId":"3ebc6a0e-d27d-4bfe-b3ef-1d0d95e8c05a"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"14777546-5b72-4dcf-b18a-15320124a0ee","displayText":"Alex Matos","occurrenceId":"c26bfbe6-b4d2-46ae-9c21-c8a411ded9f0"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"d9ef5d29-573a-4812-b717-18a783d95a70","displayText":"Michel el Buenón","occurrenceId":"bd16b8ed-b1eb-42c8-84bd-be05f092f522"}},{"text":" and ","type":"text"},{"type":"artistReference","attrs":{"artistId":"69ca4e3b-2a3a-4e61-a5bd-2210606c5f13","displayText":"David Kada","occurrenceId":"0208279a-aa02-4314-9d8b-727171ab3f9d"}},{"text":", among others.","type":"text"}]}]}'::jsonb, revision = revision + 1, updated_at = now() WHERE id = (SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id WHERE a.slug = 'chiquito-team-band' AND d.locale = 'en' AND d.document_type = 'artist_biography');
INSERT INTO editorial_entity_references (editorial_document_id, occurrence_id, entity_type, target_artist_id) VALUES ((SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id WHERE a.slug = 'chiquito-team-band' AND d.locale = 'en' AND d.document_type = 'artist_biography'), 'b7939cd8-8f7d-4e01-819f-22ac9a161303', 'artist', '0d54316a-0114-4754-ae89-72a87ed7069c');

UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Chiquito Team Band es una orquesta dominicana de salsa de Santo Domingo, dirigida por el timbalero Rafael Berroa, conocido como Chiquito, y por Emmanuel Frías. Su propio canal fecha su fundación el 30 de junio de 2012.","type":"text"}]},{"type":"paragraph","content":[{"text":"Formación","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Páginas de historia de la salsa dicen que ambos decidieron formar un proyecto nuevo llamado Chiquito Team Band, que poco a poco fue calando; un directorio musical, en cambio, fecha el grupo en 2011 y nombra a Kelvin Saviñón como cofundador. Berroa y Frías dijeron a Diario Libre en 2018 que les había costado veinte años alcanzar el éxito y que llegaron desde orígenes humildes.","type":"text"}]},{"type":"paragraph","content":[{"text":"Discos","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"El grupo publicó el sencillo «Lejos de ti» en marzo de 2014 y su primer álbum, «La industria salsera», en septiembre de 2014. «Tengo que colgar» y «Me marcho» siguieron en 2017, y su segundo álbum, «Los creadores del sonido», apareció en marzo de 2018. El sencillo «Ábreme los caminos», una canción inédita del compositor Osmany Espinosa producida por Frías, anunció ese álbum, que llevó un sonido sinfónico con arreglos de ","type":"text"},{"type":"artistReference","attrs":{"artistId":"ead3e58c-4592-489b-b5d4-0319f1f6f374","displayText":"Amaury Sánchez","occurrenceId":"dca4afb9-bcd2-4167-a168-72518ba9d61b"}},{"text":"; la banda había adelantado el concepto en el Festival Presidente. Después publicó «Me voy a gozar la vida» y «La rumba ta’ buena» (2021), «Ya supérame» (febrero de 2022) y el álbum «Sin rodeos» (septiembre de 2022).","type":"text"}]},{"type":"paragraph","content":[{"text":"Giras y premios","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"En 2018 la banda preparaba una gira por Estados Unidos y presentaciones en los carnavales de Veracruz, en México, donde dijo que se escucha su música, y recordó visitas en 2017 a Panamá, Estados Unidos, Colombia y Puerto Rico. Dijo entonces que había sido nominada a los Premios Soberano todos los años desde su debut y que había ganado cuatro estatuillas, una como Revelación y las demás como agrupación salsera del año. En marzo de 2023 Diario Libre informó que fue nombrada de nuevo mejor agrupación salsera en la ceremonia de ese año.","type":"text"}]},{"type":"paragraph","content":[{"text":"Legado","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"En 2018 Berroa nombró como otros exponentes dominicanos que mantienen vivo el género a "},{"type":"artistReference","attrs":{"occurrenceId":"8f526fb5-1ad7-4814-b245-0eed4a8291d4","artistId":"0d54316a-0114-4754-ae89-72a87ed7069c","displayText":"Yiyo Sarante"}},{"type":"text","text":", "},{"type":"artistReference","attrs":{"artistId":"e324ca2d-27a5-491b-97e7-f8c81396cfcc","displayText":"Asdrubar","occurrenceId":"591e1718-cf94-4899-a2f4-569bc3596148"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"33a84471-9f35-4a4f-9b56-b6a61e13212a","displayText":"Revolución Salsera","occurrenceId":"7bca1b91-1316-4430-8801-d2307c2c5f44"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"d1e84a54-f60c-4b1a-8c12-5195d39c6f5a","displayText":"Sexappeal","occurrenceId":"41bd6b95-3085-4178-8f71-dc04f18b1d59"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"14777546-5b72-4dcf-b18a-15320124a0ee","displayText":"Alex Matos","occurrenceId":"12ce4856-24e6-49f6-a327-6bb9409d2e60"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"d9ef5d29-573a-4812-b717-18a783d95a70","displayText":"Michel el Buenón","occurrenceId":"106584de-9029-44c5-aad1-ad841d7e5ab0"}},{"text":" y ","type":"text"},{"type":"artistReference","attrs":{"artistId":"69ca4e3b-2a3a-4e61-a5bd-2210606c5f13","displayText":"David Kada","occurrenceId":"75b06e22-8e76-46b2-8863-dcf2869d24b0"}},{"text":", entre otros.","type":"text"}]}]}'::jsonb, revision = revision + 1, updated_at = now() WHERE id = (SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id WHERE a.slug = 'chiquito-team-band' AND d.locale = 'es' AND d.document_type = 'artist_biography');
INSERT INTO editorial_entity_references (editorial_document_id, occurrence_id, entity_type, target_artist_id) VALUES ((SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id WHERE a.slug = 'chiquito-team-band' AND d.locale = 'es' AND d.document_type = 'artist_biography'), '8f526fb5-1ad7-4814-b245-0eed4a8291d4', 'artist', '0d54316a-0114-4754-ae89-72a87ed7069c');

COMMIT;
